import{_ as e,c as o,o as s,ag as a}from"./chunks/framework.Cycwnjj0.js";const r="/assets/add-classic-editor-block-in-a-post.CmrYxuV_.webp",n="/assets/add-media-option-from-the-classic-editor.dP_S4wwm.webp",i="/assets/widget-small-template.D1KNE8c0.webp",l="/assets/preview-of-widget-small.FHVevxJ1.webp",f=JSON.parse('{"title":"Widget Small Template","description":"","frontmatter":{},"headers":[],"relativePath":"guide/available-products-templates/widget-small-template.md","filePath":"guide/available-products-templates/widget-small-template.md"}'),d={name:"guide/available-products-templates/widget-small-template.md"};function p(g,t,c,m,h,u){return s(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="widget-small-template" tabindex="-1">Widget Small Template <a class="header-anchor" href="#widget-small-template" aria-label="Permalink to &quot;Widget Small Template&quot;">​</a></h1><p>AzonPress offers an advanced feature to <strong>display Amazon products</strong> using the <strong>WordPress Classic Editor</strong>. This article guides you through using the <strong>Widget Small Template</strong> of <strong>AzonPress</strong> in the <strong>Classic Editor</strong> of <strong>WordPress</strong>.</p><h2 id="widget-small-template-of-azonpress" tabindex="-1">Widget Small Template of AzonPress <a class="header-anchor" href="#widget-small-template-of-azonpress" aria-label="Permalink to &quot;Widget Small Template of AzonPress&quot;">​</a></h2><p>You can use the Widget Small template to symmetrically exhibit your products so that customers can easily conceive the ins and outs of a product.</p><p>To learn the use of the Widget Small Template, follow the steps with the screenshots below –</p><p>First, add the <strong>Classic Editor</strong> block on your desired <strong>Page/Post</strong> (e.g., I have added the classic editor to a new post).</p><p>Now, to add the <strong>Classic Editor</strong>, click the Gutenberg editor&#39;s <strong>Plus (+) icon</strong>.</p><p><img src="'+r+'" alt="Add Classic editor block in a post"></p><p>Next, click the <strong>Add Media</strong> option from the <strong>classic editor</strong> bar, and a pop-up window appears with a couple of options.</p><p><img src="'+n+'" alt="Add media option from the classic editor"></p><p>Now, press <strong>AzonPress</strong> from the left sidebar and you will get <strong>Product Templates</strong> tabs with various <strong>settings options</strong> for <strong>showcasing</strong> your <strong>Amazon products.</strong></p><ul><li>Here, you will get the <strong>Widget Small</strong> template under the <strong>Select Layout</strong> option, <strong>enable</strong> the <strong>checkbox</strong> to use this.</li><li>To learn about how to use all the other settings options under Product Templates, read this <a href="/guide/getting-started/how-to-use-azonpress-with-classic-editor-gutenberg-block.html">Documentation</a>.</li><li>Once you are done, click the <strong>Insert Shortcode</strong> button and the shortcode will be automatically embedded in your post. Then, <strong>publish</strong> it and your Amazon Products will appear on your site under that post.</li><li>If you want to <strong>showcase the same products</strong> in <strong>another post/s</strong>, you can also do it simply by <strong>copying</strong> the <strong>Shortcode</strong> visible <strong>right before</strong> the <strong>Insert Shortcode</strong> button and <strong>pasting</strong> it into the desired post/s.</li></ul><p><img src="'+i+'" alt="Widget Small Template"></p><p>Here, is the preview of the post where the selected Amazon Products are displayed as a Widget Small template.</p><p><img src="'+l+'" alt="Preview of Widget Small"></p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',17)])])}const b=e(d,[["render",p]]);export{f as __pageData,b as default};
